<?php require 'includes/functions.php';require 'includes/header.php';?><article class="legal"><span class="eyebrow">YOUR PRIVACY MATTERS</span><h1><?=e(t('นโยบายความเป็นส่วนตัว'))?></h1><p><?=e(t('ฉบับร่างสำหรับเว็บไซต์สาธิต · เวอร์ชัน 2026-11-03'))?></p><h2><?=e(t('ข้อมูลที่เก็บและวัตถุประสงค์'))?></h2><p><?=e(t('ชื่อ อีเมล รหัสผ่านที่ผ่านการแฮช ข้อมูลติดต่อ ที่อยู่ และประวัติคำสั่งซื้อ ใช้จัดการบัญชี จัดส่งสินค้า และให้บริการลูกค้า บันทึกการเข้าสู่ระบบใช้ป้องกันการเดารหัสผ่าน ไม่เก็บข้อมูลบัตรชำระเงิน'))?></p><h2><?=e(t('ที่อยู่จัดส่งที่สมาชิกเลือกบันทึก'))?></h2><p><?=e(t('สมุดที่อยู่เก็บชื่อผู้รับ เบอร์โทร บ้านเลขที่ ตำบล อำเภอ จังหวัด รหัสไปรษณีย์ จุดสังเกต และลิงก์แผนที่ที่เลือกกรอก เพื่อเติมข้อมูลการสั่งซื้อครั้งต่อไป บันทึกเฉพาะเมื่อสมาชิกเลือกยืนยัน สมาชิกดู แก้ไข ลบ และตั้งที่อยู่เริ่มต้นได้ในหน้าที่อยู่ของฉัน ที่อยู่จากคำสั่งซื้อเก่าจะไม่ถูกนำมาบันทึกโดยอัตโนมัติ การแก้หรือลบสมุดที่อยู่ไม่เปลี่ยนสำเนาที่อยู่ในคำสั่งซื้อเดิมซึ่งเก็บตามนโยบายประวัติคำสั่งซื้อ'))?></p><h2><?=e(t('คูปอง โปรโมชั่น และข้อมูลผู้รับชำระ'))?></h2><p><?=e(t('บันทึกประวัติใช้สิทธิ์โปรโมชั่นเชื่อมกับบัญชีและคำสั่งซื้อ เพื่อจำกัดสิทธิ์ตามเงื่อนไขและป้องกันใช้ซ้ำ เก็บสำเนาราคาหลังส่วนลด บริการขนส่ง และผู้รับชำระที่แสดงในคำสั่งซื้อ QR พร้อมเพย์สร้างภายในเว็บไซต์ ไม่ส่งหมายเลขผู้รับหรือยอดให้บริการสร้าง QR ภายนอก ปัจจุบันยังไม่ได้เปิด Payment Gateway สำหรับบัตรหรือ e-Wallet และไม่มีการเก็บหมายเลขบัตรเต็มหรือ CVV'))?></p><h2><?=e(t('การชำระเงินและหลักฐานการโอน'))?></h2><p><?=e(t('เมื่อเลือกโอนเงิน ระบบจัดเก็บภาพสลิปเพื่อให้ผู้ดูแลตรวจสอบการชำระเงิน ภาพอาจมีชื่อผู้โอน บัญชีบางส่วน ยอดเงิน และข้อมูลรายการธนาคาร จำกัดการเข้าถึงเฉพาะเจ้าของคำสั่งซื้อและผู้ดูแล เก็บประวัติการตรวจสอบ เหตุผลที่ไม่ผ่าน และการเปลี่ยนสถานะพร้อมผู้ดำเนินการ ไม่ใช้ภาพสลิปเพื่อการตลาด ไม่ตรวจยอดเงินจริงอัตโนมัติ และไม่ส่งสลิปไปผู้ให้บริการภายนอก ระยะเวลาเก็บหลักฐานและวิธีลบต้องได้รับอนุมัติจากเจ้าของร้านก่อนเปิดบริการจริง ปัจจุบันยังไม่มีระบบลบสลิปตามกำหนด'))?></p><h2><?=e(t('ข้อความติดต่อร้านค้า'))?></h2><p><?=e(t('แบบฟอร์มติดต่อเก็บชื่อ อีเมล เบอร์โทรศัพท์ที่เลือกกรอก หัวข้อ ข้อความ และเวลาที่ส่ง เพื่อรับเรื่อง ตรวจสอบ และติดต่อกลับ เฉพาะผู้ดูแลร้านค้าเข้าถึงได้ ระบบบันทึกเวอร์ชันข้อความแจ้งการใช้ข้อมูล 2026-11-09 และค่าแฮชของ Session เพื่อจำกัดการส่งซ้ำ ไม่เก็บ IP ในตารางข้อความ และไม่ใช้ข้อความเพื่อสมัครรับข่าวสาร การกำหนดระยะเวลาเก็บและการลบข้อความยังต้องได้รับการอนุมัติจากเจ้าของร้านก่อนเปิดบริการจริง'))?></p><h2><?=e(t('สถิติการเข้าชม'))?></h2><p><?=e(t('นับการเปิดหน้าสาธารณะเป็นยอดรวมรายวันและชื่อหน้า เก็บย้อนหลังไม่เกิน 90 วัน โดยไม่เก็บ IP รหัสผู้เข้าชม อีเมล ข้อความค้นหา หรือคุกกี้ติดตาม ไม่ได้ใช้ Google Analytics หรือ Facebook Pixel และไม่ส่งข้อมูลสถิติไปยังบริการภายนอก ตัวนับนี้อาจรวมการรีเฟรชและบอต จึงไม่ใช่จำนวนบุคคล'))?></p><h2><?=e(t('ความยินยอมและคุกกี้'))?></h2><p><?=e(t('ใช้คุกกี้ Session เพื่อเข้าสู่ระบบและตะกร้า การรับข่าวสารเป็นทางเลือกและไม่เลือกไว้ล่วงหน้า สามารถถอนความยินยอมในหน้าบัญชี ระบบเก็บเวอร์ชันนโยบาย เวลา และการเปลี่ยนความยินยอม'))?></p><h2><?=e(t('การเก็บรักษาและการเปิดเผย'))?></h2><p><?=e(t('ข้อเสนอสำหรับผู้รับผิดชอบตรวจสอบ: เก็บข้อมูลบัญชีตลอดระยะเวลาใช้บริการ ประวัติคำสั่งซื้อ 5 ปี และบันทึกความพยายามเข้าสู่ระบบ 30 วัน การลบอัตโนมัติยังไม่ได้เปิดใช้ ระยะเวลาจริงและฐานการประมวลผลต้องได้รับการอนุมัติก่อนเปิดบริการ เปิดเผยข้อมูลจัดส่งเฉพาะผู้ให้บริการที่จำเป็น และจำกัดหลังร้านเฉพาะผู้ดูแล'))?></p><h2><?=e(t('สิทธิและช่องทางติดต่อ'))?></h2><p><?=e(t('ส่งคำขอเข้าถึงหรือขอลบข้อมูลได้ที่'))?> <a href="privacy_request.php"><?=e(t('แบบฟอร์มคำขอ'))?></a> <?=e(t('หรือติดต่อร้านผ่าน'))?> <a href="contact.php"><?=e(t('หน้าติดต่อเรา'))?></a> <?=e(t('และถอนความยินยอมได้ในหน้าบัญชี ผู้ดูแลต้องตรวจสอบตัวตนและเหตุจำเป็นในการเก็บข้อมูลก่อนดำเนินการ'))?></p><div class="notice"><?=e(t('ก่อนเปิดใช้จริง เจ้าของร้านต้องระบุผู้ควบคุมข้อมูล ระยะเวลาเก็บรักษาที่อนุมัติ ผู้ให้บริการภายนอก และกระบวนการตอบคำขอ รวมทั้งให้ผู้รับผิดชอบตรวจสอบนโยบายนี้'))?></div></article><section><h2><?=e(t('พิกัดจัดส่งและบริการแผนที่'))?></h2><p><?=e(t('พิกัดเป็นข้อมูลทางเลือก บันทึกกับสมุดที่อยู่เฉพาะเมื่อยินยอม และเก็บสำเนากับคำสั่งซื้อเพื่อจัดส่ง เฉพาะเจ้าของบัญชีและผู้ดูแลเข้าถึงได้ สามารถกรอกที่อยู่โดยไม่ใช้พิกัดได้ เปิดแผนที่จึงติดต่อ OpenStreetMap ซึ่งได้รับ IP และพื้นที่ภาพที่เปิด ค้นชื่อสถานที่จึงส่งคำค้นไป Photon โดยแคชผลไม่เกินหนึ่งวัน กรุณาไม่ค้นด้วยชื่อผู้รับหรือข้อมูลส่วนตัว ตำแหน่งปัจจุบันขอสิทธิ์จากเบราว์เซอร์เมื่อกดปุ่มเท่านั้น ไม่มีการติดตามเบื้องหลัง ระยะเวลาเก็บพิกัดในคำสั่งซื้อต้องให้เจ้าของร้านอนุมัติก่อนเปิดบริการจริง'))?></p></section><?php require 'includes/footer.php';?>
